function render(){
  const normalized=query.trim().toLowerCase();let functionCount=0;
  if(normalized){
    const entries=matchingFunctions(normalized);for(const entry of API.functions)if(revealedReferences.has(entry.owner+'-'+entry.name)&&!entries.includes(entry))entries.push(entry);functionCount=entries.length;
    sections.innerHTML=entries.length?'<section class="api-section"><div class="section-heading"><div><h2>Matching functions</h2></div><span>'+entries.length+' results · name matches first</span></div><div class="function-list">'+entries.map(card).join('')+'</div></section>':'';
  }else{
  sections.innerHTML=owners.map((owner,index)=>{const entries=API.functions.filter(entry=>entry.owner===owner&&(!normalized||queryMatches(normalized,entry.owner,entry.name,entry.signature,entry.description,entry.note,entry.params.map(item=>[item.name,item.type,item.description]),entry.returns.map(item=>[item.name,item.type,item.description]))));if(!entries.length)return"";functionCount+=entries.length;return'<section class="api-section" id="category-'+esc(owner)+'"><div class="section-heading"><div><span class="section-number">'+String(index+1).padStart(2,"0")+'</span><h2>'+esc(categoryLabels[owner]||owner)+'</h2></div><span>'+entries.length+' '+(entries.length===1?'function':'functions')+'</span></div><div class="function-list">'+entries.map(card).join("")+'</div></section>'}).join("");
  }
  const showData=true;
  const dataCount=showData?renderData(normalized):0;
  dataSections.classList.toggle("hidden",!showData||dataCount===0);
  empty.classList.toggle("hidden",functionCount+dataCount>0);
  empty.textContent=normalized?'No API entries match “'+query+'”.':'No API entries found.';
  scheduleSidebarHighlight();
}
let sidebarHighlightFrame=0;
function scheduleSidebarHighlight(){
  if(!sidebarHighlightFrame)sidebarHighlightFrame=requestAnimationFrame(updateSidebarHighlight);
}
function updateSidebarHighlight(){
  sidebarHighlightFrame=0;
  const boundary=document.querySelector('.topbar').getBoundingClientRect().bottom+32;
  const links=[...document.querySelectorAll('.sidebar nav a')];
  const candidates=links.flatMap(link=>{
    const id=link.hash.slice(1),section=document.getElementById(id);
    if(section)return [{link,element:section}];
    if(query.trim()&&id.startsWith('category-'))return API.functions.filter(entry=>entry.owner===id.slice(9)).flatMap(entry=>{
      const card=document.getElementById(entry.owner+'-'+entry.name);
      return card?[{link,element:card}]:[];
    });
    return [];
  }).map(item=>({...item,rect:item.element.getBoundingClientRect()})).filter(item=>item.rect.bottom>boundary).sort((a,b)=>a.rect.top-b.rect.top);
  const current=candidates.find(item=>item.rect.top<=boundary)||candidates.find(item=>item.rect.top<(query.trim()?innerHeight:Math.min(innerHeight/2,boundary+120)))||(!query.trim()&&scrollY<100?candidates[0]:null);
  for(const link of links){
    const active=link===current?.link;
    link.classList.toggle('active-section',active);
    if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');
  }
}
window.addEventListener('scroll',scheduleSidebarHighlight,{passive:true});
