let jumpFrame=0;
function fastJump(target,hash){
  if(target.matches('details'))target.open=true;
  cancelAnimationFrame(jumpFrame);
  if(hash)history.pushState(null,"",hash);
  const margin=parseFloat(getComputedStyle(target).scrollMarginTop)||0;
  const start=window.scrollY;
  const destination=Math.max(0,target.getBoundingClientRect().top+start-margin);
  const distance=destination-start;
  if(matchMedia("(prefers-reduced-motion: reduce)").matches||Math.abs(distance)<2){window.scrollTo(0,destination);return}
  const started=performance.now(),duration=120;
  const step=now=>{const progress=Math.min(1,(now-started)/duration);const eased=1-Math.pow(1-progress,3);window.scrollTo(0,start+distance*eased);if(progress<1)jumpFrame=requestAnimationFrame(step)};
  jumpFrame=requestAnimationFrame(step);
}
const referenceDialog=document.createElement('div');
