let referenceHistory=[],referenceOpener=null;
function positionReference(){
  if(!referenceDialog.matches(':popover-open')||!referenceOpener?.isConnected)return;
  const anchor=referenceOpener.getBoundingClientRect();
  const block=(referenceOpener.closest('.detail-row > *, .property-row > *')||referenceOpener).getBoundingClientRect();
  const gap=10,edge=12,top=document.querySelector('.topbar').getBoundingClientRect().bottom+edge;
  const width=Math.min(620,innerWidth-2*edge),height=Math.min(480,innerHeight-top-edge);
  const clamp=(n,min,max)=>Math.max(min,Math.min(n,max));
  let x=clamp(anchor.left,edge,innerWidth-width-edge),y,maxHeight=height,panelWidth=width;
  // Avoid the clicked cell (row/column intersection), not its entire row or column.
  if(innerWidth-block.right-gap-edge>=340){panelWidth=Math.min(width,innerWidth-block.right-gap-edge);x=block.right+gap;y=clamp(anchor.top,top,innerHeight-height-edge);}
  else if(block.left-gap-edge>=340){panelWidth=Math.min(width,block.left-gap-edge);x=block.left-gap-panelWidth;y=clamp(anchor.top,top,innerHeight-height-edge);}
  else if(innerHeight-block.bottom-gap-edge>=180){y=block.bottom+gap;maxHeight=Math.min(height,innerHeight-y-edge);}
  else if(block.top-gap-top>=180){maxHeight=Math.min(height,block.top-gap-top);y=block.top-gap-maxHeight;}
  else{
    // On constrained screens, preserve the clicked line and overlap only as needed.
    const below=innerHeight-anchor.bottom-gap-edge,above=anchor.top-gap-top;
    maxHeight=Math.max(100,Math.min(height,Math.max(below,above)));
    y=below>=above?anchor.bottom+gap:anchor.top-gap-maxHeight;
    y=clamp(y,top,innerHeight-maxHeight-edge);
  }
  Object.assign(referenceDialog.style,{left:x+'px',top:y+'px',width:panelWidth+'px',maxHeight:maxHeight+'px'});
}
window.addEventListener('scroll',positionReference,{passive:true});
