  const type=API.types.find(item=>id==='type-'+item.name);
  if(type)return {title:type.name,html:'<div class="type-description">'+typeDescription(type)+'</div>'+API.properties.filter(item=>item.owner===(type.name==='Script'?'script':type.name)).map(item=>'<div class="property-row"><code>'+esc(item.name)+'</code><code>'+linkedType(item.type)+'</code><div>'+propertyDescription(item.description)+'</div></div>').join('')};
  const property=API.properties.find(item=>id==='property-'+item.owner+'-'+item.name);
  if(property)return {title:property.owner+'.'+property.name,html:'<div class="method-description"><code class="type">'+linkedType(property.type)+'</code>'+propertyDescription(property.description)+'</div>'};
  const enumeration=API.enums.find(item=>id==='enum-'+item.name);
  if(enumeration)return {title:enumeration.name,html:'<div class="enum-body">'+docBlocks(enumeration.description||'')+'<div class="enum-groups">'+groupEnum(enumeration.name,enumeration.values).map(([label,values])=>'<section class="enum-group">'+(label?'<h3>'+esc(label)+'</h3>':'')+'<div class="enum-values">'+values.map(value=>'<code>'+esc(value)+'</code>').join('')+'</div></section>').join('')+'</div></div>'};
